//! The Atari ST system fonts (EmuTOS `fnt_st_6x6`/`fnt_st_8x8`/`fnt_st_8x16`).
//!
//! Glyph bitmaps are generated by `cargo xtask gen-font` into
//! [`font_data`](super::font_data) (one byte-array per character,
//! `form_height` rows, MSB = leftmost pixel). The metrics below are the
//! EmuTOS font-header (`Fonthead`) values.
//!
//! Two layers live here:
//!
//! * The [`SysFont`] ring ([`FON_6X6`]/[`FON_8X8`]/[`FON_8X16`], EmuTOS
//!   `font_ring[]` / `vdi_text.c:604`) that `vst_height`/`vst_point` select
//!   among and that `v_gtext` renders with, plus the two screen-height rules
//!   that pick the default face from it: [`text_init_def_font`] (the VDI's and
//!   so the AES's) and [`font_set_default`] (the VT52 console's). Under 400
//!   lines both are the 8×8 face, from 400 lines up the 8×16 face (V32).
//! * The `pub const` metrics + [`glyph`] of the **8×16 face** alone
//!   (`fnt_st_8x16`). They are that face's numbers, not "the" system font:
//!   code that draws in the default font asks [`text_init_def_font`] /
//!   [`font_set_default`] for the face and reads [`glyph_rows`].
//! * The loaded-font chain (`vst_load_fonts`, EmuTOS `font_ring[2]`,
//!   `TASK/V33.md`): [`FontRef`], [`head`], the ring walk and the swap of a font
//!   without `F_STDFORM` ([`trnsfont`]).
//!
//! **Byte order of a glyph table.** A row is a stream of bytes, leftmost byte
//! first, bit 7 = leftmost pixel — the built-in rasters above and, read through
//! [`read_mem`], a loaded `dat_table` alike. That is the Motorola byte order
//! `F_STDFORM` names (`include/fonthdr.h:23`): EmuTOS' big-endian word read with
//! `0x8000 >> (SOURCEX & 15)` (`vdi/vdi_textblit.c:1232-1233`, `:1059`) walks the
//! same bits as this byte stream, on any CPU. So the rule stays EmuTOS' own: a
//! header with `F_STDFORM` is left alone, one without gets its table byte-swapped
//! word by word **in memory**, and that swap ([`trnsfont`]) does the same to the
//! bytes on a little-endian CPU as `ror #8` does on the 68000.

use core::cell::UnsafeCell;

use super::Vdipb;
use crate::bdos::process;
use crate::bdos::process::usermem;
use crate::bdos::process::Abi;
use crate::uaccess::Space;

pub use super::font_data::{SYSTEM_FONT_6X6, SYSTEM_FONT_8X16, SYSTEM_FONT_8X8};

/// Character cell width of the 8×16 face in pixels (monospace).
pub const CELL_W: i16 = 8;
/// Character cell height of the 8×16 face in pixels — **not** the default
/// font's on every screen (8 under 400 lines, [`text_init_def_font`]).
pub const CELL_H: i16 = 16;
/// Baseline distance from the top of the cell (`top`).
pub const TOP: i16 = 13;
/// Half-line distance from the baseline (`half`).
pub const HALF: i16 = 8;
/// Ascent (cap-top) distance from the baseline.
pub const ASCENT: i16 = 11;
/// Descent distance below the baseline.
pub const DESCENT: i16 = 2;

// Remaining `Fonthead` metrics for `fnt_st_8x16` (EmuTOS
// `bios/fnt_st_8x16.c`), reported by the text inquiry/attribute opcodes.
/// Font face id (`font_id`).
pub const FONT_ID: i16 = 1;
/// Nominal point size (`point`).
pub const POINT: i16 = 10;
/// First character code present (`first_ade`).
pub const FIRST_ADE: i16 = 0;
/// Last character code present (`last_ade`).
pub const LAST_ADE: i16 = 255;
/// Maximum glyph width in pixels (`max_char_width`).
pub const MAX_CHAR_WIDTH: i16 = 7;
/// Bold (thicken) horizontal overstrike in pixels (`thicken`).
pub const THICKEN: i16 = 1;
/// Underline thickness in pixels (`ul_size`).
pub const UL_SIZE: i16 = 1;
/// Lighten (greying) AND-mask applied per glyph row (`lighten`).
pub const LIGHTEN: u8 = 0x55;
/// Skew (italic) shift mask, one bit per scanline (`skew`).
pub const SKEW: u16 = 0x5555;
/// Left offset of the glyph within the cell (`left_offset`).
pub const LEFT_OFFSET: i16 = 1;
/// Right offset of the glyph within the cell (`right_offset`).
pub const RIGHT_OFFSET: i16 = 7;
/// Distance from the baseline to the cell bottom (`bottom`).
pub const BOTTOM: i16 = 2;
/// Name string (`name`), reported by `vqt_name`.
pub const NAME: &[u8] = b"8x16 system font";
/// `vqt_name` font-name field length in WORDs (GEM `Fonthead.name`).
pub const NAME_LEN: usize = 32;

/// The 16-row bitmap for character `c` (low 8 bits select the glyph) in the
/// 8×16 face. For the default font of a screen use [`glyph_rows`].
#[inline]
pub fn glyph(c: u16) -> &'static [u8; 16] {
    &SYSTEM_FONT_8X16[(c & 0xFF) as usize]
}

// ── the AES's second desktop font size ("SMALL") ─────────────────────
//
// EmuTOS `gsx_start` (gemgraf.c:405-410) keeps **two** cell sizes for the
// AES to draw with:
//
//   gsx_textsize(&gl_wptschar, &gl_hptschar, &gl_wchar, &gl_hchar);
//   gl_ws.ws_chmaxh = gl_hptschar;            /* the IBM (normal) font */
//   vst_height(gl_ws.ws_chminh, &gl_wsptschar, &gl_hsptschar,
//              &gl_wschar, &gl_hschar);       /* the SMALL font       */
//
// `ws_chminh` is `SIZ_TAB[1]` from `v_opnwk` — the smallest `top` across
// the system face (`vdi_text.c:635-636`), which for the ring below is the
// 6×6 face's `top = 4` (our [`super::workstation::siz_tab`] folds the same
// ring and reports the same 4). `vst_height(4)` then selects the 6×6 face
// (`vdi_text.c:706-713`: the largest font whose `top <= 4`) and returns
// `cell_width = max_cell_width = 6`, `cell_height = top + bottom + 1 = 6`
// (`setup_width_height`, `vdi_text.c:666-679`).
//
// `SIZ_TAB[1]` folds the whole ring and so does not depend on the screen:
// on every screen the AES's SMALL font is the 6×6 face, and the two
// constants below are `gl_wschar`/`gl_hschar`. (The normal font,
// `gl_wchar`/`gl_hchar`, is the screen's [`text_init_def_font`].) The unit test at the
// bottom of this module re-derives both from [`RING`] so they cannot drift.

/// The AES SMALL-font cell width — EmuTOS `gl_wschar` (`gemgraf.c:42`).
/// Used by `gr_gicon` for an icon's overlay character and its label, and
/// by any `TEDINFO` whose `te_font` is `SMALL`.
pub const SMALL_CELL_W: i16 = 6;
/// The AES SMALL-font cell height — EmuTOS `gl_hschar` (`gemgraf.c:43`).
pub const SMALL_CELL_H: i16 = 6;

/// The 6-row bitmap for character `c` (low 8 bits select the glyph) in the
/// AES SMALL font. The 6 pixels are packed into bits 7..2 of each row, the
/// layout [`super::backend::RasterBackend::draw_glyph_sized`] expects for a
/// `cell_w` of 6.
#[inline]
pub fn glyph_small(c: u16) -> &'static [u8; 6] {
    &SYSTEM_FONT_6X6[(c & 0xFF) as usize]
}

/// One of the three built-in system-font sizes. The discriminant is the
/// ring index (EmuTOS `font_ring[0..2]`, smallest first).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SysFontId {
    /// 6×6 system font (`fnt_st_6x6`).
    F6x6 = 0,
    /// 8×8 system font (`fnt_st_8x8`).
    F8x8 = 1,
    /// 8×16 system font (`fnt_st_8x16`).
    F8x16 = 2,
}

/// A font header as the text path (`v_gtext`, `vst_height`/`vst_point`)
/// consumes it: the EmuTOS `Fonthead` metrics, plus where the glyphs are. For a
/// built-in system font that is the [`SysFontId`] (all three have `font_id = 1`,
/// standard mono format, first/last ade 0/255; `loaded` is `None`). For a font of
/// a chain ([`head`]) `loaded` holds its tables and `id`/`name` mean nothing.
///
/// `Copy` so the scaled scratch header EmuTOS keeps in `vwk->scratch_head`
/// (`vdi_text.c:770-817`) can be produced by value on demand.
#[derive(Clone, Copy)]
pub struct SysFont {
    /// Which raster this font's glyphs come from.
    pub id: SysFontId,
    /// Face id (`font_id`) — 1 for all three system fonts.
    pub font_id: i16,
    /// Nominal point size (`point`), used by `vst_point` selection.
    pub point: i16,
    /// First character code present (`first_ade`).
    pub first_ade: i16,
    /// Last character code present (`last_ade`).
    pub last_ade: i16,
    /// Baseline distance from the cell top (`top`), used by `vst_height`.
    pub top: i16,
    /// Ascent (cap-top) distance from the baseline (`ascent`).
    pub ascent: i16,
    /// Half-line distance from the baseline (`half`).
    pub half: i16,
    /// Descent distance below the baseline (`descent`).
    pub descent: i16,
    /// Distance from the baseline to the cell bottom (`bottom`).
    pub bottom: i16,
    /// Maximum glyph width (`max_char_width`).
    pub max_char_width: i16,
    /// Cell advance width (`max_cell_width`).
    pub max_cell_width: i16,
    /// Glyph left offset within the cell (`left_offset`).
    pub left_offset: i16,
    /// Glyph right offset within the cell (`right_offset`).
    pub right_offset: i16,
    /// Bold overstrike in pixels (`thicken`).
    pub thicken: i16,
    /// Underline thickness in pixels (`ul_size`).
    pub ul_size: i16,
    /// Lighten (greying) AND-mask (`lighten`).
    pub lighten: u16,
    /// Skew (italic) shift mask (`skew`).
    pub skew: u16,
    /// Number of scanlines per glyph (`form_height`) = cell height.
    pub form_height: i16,
    /// Face name (`name`), NUL-free.
    pub name: &'static [u8],
    /// `flags & F_DEFAULT` (`include/fonthdr.h:21`) — a face [`text_init_def_font`]
    /// may choose as the default. Set on the 8×8 and the 8×16 face
    /// (`bios/fnt_st_8x8.c:165`, `bios/fnt_st_8x16.c:293`), not on the 6×6
    /// (`bios/fnt_st_6x6.c:109`).
    pub f_default: bool,
    /// The tables of a font from a chain; `None` for a built-in font.
    pub loaded: Option<LoadedTables>,
}

impl SysFont {
    /// `flags & F_MONOSPACE`: every built-in font is monospaced.
    #[inline]
    pub fn mono(&self) -> bool {
        self.loaded.is_none_or(|t| t.flags & F_MONOSPACE != 0)
    }

    /// The face name (`vqt_name`), at most [`NAME_LEN`] bytes.
    #[inline]
    pub fn name_bytes(&self) -> &[u8] {
        match &self.loaded {
            Some(t) => &t.name,
            None => self.name,
        }
    }
}

